(1801160, 243778, 46049, '<td valign="top">This is an extremely cool picture!!!  Really artistic!!!</td>', 'This is an extremely cool picture!!!  Really artistic!!!', '2005-10-21 14:02:15.000000', NULL, 1),
(1801358, 245224, 43753, '<td valign="top">There is a surreal quality to this photo that makes it very cool. I think tree is distracting. I wish you could have gotten closer to the subject w/no tree and still kept the moon. Still a really cool idea. I would like to see how you did this.</td>', 'There is a surreal quality to this photo that makes it very cool. I think tree is distracting. I wish you could have gotten closer to the subject w/no tree and still kept the moon. Still a really cool idea. I would like to see how you did this.', '2005-10-21 15:49:12.000000', NULL, 1),
(1801362, 244184, 43753, '<td valign="top">I love the subject, and the lighting seems good. I think the composition would benefit if you zoomed in a little more on the plumes, and if you cropped out a little of the right hand side of frame.</td>', 'I love the subject, and the lighting seems good. I think the composition would benefit if you zoomed in a little more on the plumes, and if you cropped out a little of the right hand side of frame.', '2005-10-21 15:50:32.000000', NULL, 1),
(1801365, 244961, 43753, '<td valign="top">I like the line of trees, and your lighting is great - it produced strong shadows.</td>', 'I like the line of trees, and your lighting is great - it produced strong shadows.', '2005-10-21 15:51:45.000000', NULL, 1),
(1801368, 246052, 43753, '<td valign="top">Very cute kitty, but the image seems too noisy.</td>', 'Very cute kitty, but the image seems too noisy.', '2005-10-21 15:52:17.000000', NULL, 1),
