(1801382, 245474, 43753, '<td valign="top">There is nice texture, and the shadow idea is a good one, but there isn''t really anything about the shadow that I find remarkable.</td>', 'There is nice texture, and the shadow idea is a good one, but there isn''t really anything about the shadow that I find remarkable.', '2005-10-21 15:56:53.000000', NULL, 1),
