(1802255, 246384, 30881, '<td valign="top">Great idea. Nice color combinations Like the blurred movement. Would work well as a textured background.</td>', 'Great idea. Nice color combinations Like the blurred movement. Would work well as a textured background.', '2005-10-21 21:46:29.000000', NULL, 1),
